import { Controller, Get, Post, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 허용 인증기기 수 설정(auth_setting)이 없을 때 쓰는 기본값
const DEFAULT_ALLOWED_DEVICE_COUNT = 1;
// 가정: 반려 사유가 없을 때 저장하는 문구 (반려 시 reject_reason은 필수 컬럼)
const DEFAULT_REJECT_REASON = '사유 없음';
const APPROVAL_STATUSES = ['신청', '승인', '반려'];

type Db = Parameters<Parameters<typeof transaction>[0]>[0];

function validationFailed(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function text(value: unknown): string {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
}

function idOf(req: Request): string {
  const value = req.params['authDeviceId'];
  if (!/^\d+$/.test(value)) {
    throw validationFailed('인증기기 ID 형식이 올바르지 않습니다.');
  }
  return value;
}

async function loadDevice(db: Db, id: string) {
  const rows = await db.query(
    `SELECT auth_device_id AS "authDeviceId", employee_id AS "employeeId", approval_status AS "approvalStatus"
       FROM auth_device
      WHERE auth_device_id = CAST(:id AS bigint)
        FOR UPDATE`,
    { id },
  );
  if (rows.length === 0) {
    throw new ApiError(404, 'AUTH_DEVICE_NOT_FOUND', '인증기기를 찾을 수 없습니다.');
  }
  return rows[0];
}

async function writeHistory(db: Db, userId: string, targetId: number | string, changeType: string, content: string) {
  await db.execute(
    `INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at)
     VALUES (CAST(:userId AS bigint), 'auth_device', CAST(:targetId AS bigint), :changeType, now(), :content, now(), now())`,
    { userId, targetId: String(targetId), changeType, content },
  );
}

async function writeNotification(db: Db, recipientId: number | string, targetId: number | string, eventType: string, title: string, content: string) {
  await db.execute(
    `INSERT INTO notification (recipient_id, channel, title, content, read_status, event_type, target_type, target_id, created_at, updated_at)
     VALUES (CAST(:recipientId AS bigint), '포털', :title, :content, '안읽음', :eventType, 'AUTH_DEVICE', CAST(:targetId AS bigint), now(), now())`,
    { recipientId: String(recipientId), title, content, eventType, targetId: String(targetId) },
  );
}

@Controller('api/v1')
export class FnSfr03703Controller {
  @Get('/auth-devices')
  async listAuthDevices(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자', '임직원');
    const query = checks.queryOf(req.query);
    const approvalStatus = text(query['approvalStatus']);
    if (approvalStatus !== '' && !APPROVAL_STATUSES.includes(approvalStatus)) {
      throw validationFailed('승인 상태 값이 올바르지 않습니다.');
    }
    const employeeId = text(query['employeeId']);
    if (employeeId !== '' && !/^\d+$/.test(employeeId)) {
      throw validationFailed('임직원 ID는 숫자여야 합니다.');
    }
    const pageText = text(query['page']) || '0';
    const sizeText = text(query['size']) || '20';
    if (!/^\d+$/.test(pageText) || !/^\d+$/.test(sizeText)) {
      throw validationFailed('page와 size는 0 이상의 정수여야 합니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), 200);
    const params = {
      approvalStatus: approvalStatus === '' ? null : approvalStatus,
      employeeId: employeeId === '' ? null : employeeId,
      limit: size,
      offset: page * size,
    };
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT auth_device_id AS "authDeviceId",
                employee_id AS "employeeId",
                device_name AS "deviceName",
                device_identifier AS "deviceIdentifier",
                approval_status AS "approvalStatus",
                use_status AS "useStatus"
           FROM auth_device
          WHERE (CAST(:approvalStatus AS varchar) IS NULL OR approval_status = CAST(:approvalStatus AS varchar))
            AND (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))
          ORDER BY auth_device_id DESC
          LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM auth_device
          WHERE (CAST(:approvalStatus AS varchar) IS NULL OR approval_status = CAST(:approvalStatus AS varchar))
            AND (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))`,
        { approvalStatus: params.approvalStatus, employeeId: params.employeeId },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/auth-devices')
  @HttpCode(200)
  async createAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const deviceIdentifier = text(data['deviceIdentifier']);
    const deviceName = text(data['deviceName']);
    if (deviceIdentifier === '' || deviceIdentifier.length > 200) {
      throw validationFailed('기기 식별정보를 200자 이내로 입력해 주세요.');
    }
    if (deviceName.length > 100) {
      throw validationFailed('기기명은 100자 이내로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const duplicated = await db.query(
        `SELECT auth_device_id AS "authDeviceId"
           FROM auth_device
          WHERE employee_id = CAST(:userId AS bigint)
            AND device_identifier = :deviceIdentifier
            AND approval_status IN ('신청', '승인')`,
        { userId: user.id, deviceIdentifier },
      );
      if (duplicated.length > 0) {
        throw new ApiError(409, 'AUTH_DEVICE_DUPLICATED', '이미 등록 요청된 기기입니다.');
      }
      const rows = await db.query(
        `INSERT INTO auth_device (employee_id, device_identifier, device_name, otp_enabled, approval_status, use_status, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), :deviceIdentifier, :deviceName, true, '신청', '미사용', now(), now())
         RETURNING auth_device_id AS "authDeviceId", approval_status AS "approvalStatus"`,
        { userId: user.id, deviceIdentifier, deviceName: deviceName === '' ? null : deviceName },
      );
      const created = rows[0];
      await writeHistory(db, user.id, created.authDeviceId, '등록 요청', '인증기기 등록을 요청했습니다.');
      await writeNotification(db, user.id, created.authDeviceId, 'AUTH_DEVICE_REQUESTED', '인증기기 등록 요청', '인증기기 등록 요청이 접수되었습니다. 승인 결과를 기다려 주세요.');
      return created;
    });
  }

  @Post('/auth-devices/:authDeviceId/approve')
  @HttpCode(200)
  async approveAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const id = idOf(req);
    return transaction(async (db) => {
      const device = await loadDevice(db, id);
      if (device.approvalStatus !== '신청') {
        throw new ApiError(409, 'AUTH_DEVICE_ALREADY_PROCESSED', '이미 승인·반려 처리된 요청입니다.');
      }
      const settings = await db.query(
        `SELECT allowed_device_count AS "allowedCount"
           FROM auth_setting
          WHERE employee_id = CAST(:employeeId AS bigint) OR employee_id IS NULL
          ORDER BY (employee_id IS NULL) ASC
          LIMIT 1`,
        { employeeId: String(device.employeeId) },
      );
      const allowed = settings.length > 0 ? Number(settings[0].allowedCount) : DEFAULT_ALLOWED_DEVICE_COUNT;
      const counts = await db.query(
        `SELECT COUNT(*) AS "count"
           FROM auth_device
          WHERE employee_id = CAST(:employeeId AS bigint)
            AND approval_status = '승인'`,
        { employeeId: String(device.employeeId) },
      );
      if (Number(counts[0].count) >= allowed) {
        throw new ApiError(422, 'ALLOWED_DEVICE_COUNT_EXCEEDED', '허용 인증기기 수(' + allowed + '대)를 초과하여 승인할 수 없습니다.');
      }
      const rows = await db.query(
        `UPDATE auth_device
            SET approval_status = '승인',
                use_status = '사용',
                approver_id = CAST(:userId AS bigint),
                processed_at = now(),
                updated_at = now()
          WHERE auth_device_id = CAST(:id AS bigint)
          RETURNING auth_device_id AS "authDeviceId", approval_status AS "approvalStatus"`,
        { id, userId: user.id },
      );
      await writeHistory(db, user.id, id, '승인', '인증기기를 승인했습니다.');
      await writeNotification(db, device.employeeId, id, 'AUTH_DEVICE_APPROVED', '인증기기 승인', '인증기기 등록 요청이 승인되었습니다.');
      return rows[0];
    });
  }

  @Post('/auth-devices/:authDeviceId/reject')
  @HttpCode(200)
  async rejectAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const id = idOf(req);
    const data = checks.inputOf(req.body);
    const reason = text(data['rejectReason']);
    if (reason.length > 500) {
      throw validationFailed('반려 사유는 500자 이내로 입력해 주세요.');
    }
    const rejectReason = reason === '' ? DEFAULT_REJECT_REASON : reason;
    return transaction(async (db) => {
      const device = await loadDevice(db, id);
      if (device.approvalStatus !== '신청') {
        throw new ApiError(409, 'AUTH_DEVICE_ALREADY_PROCESSED', '이미 승인·반려 처리된 요청입니다.');
      }
      const rows = await db.query(
        `UPDATE auth_device
            SET approval_status = '반려',
                reject_reason = :rejectReason,
                approver_id = CAST(:userId AS bigint),
                processed_at = now(),
                updated_at = now()
          WHERE auth_device_id = CAST(:id AS bigint)
          RETURNING auth_device_id AS "authDeviceId", approval_status AS "approvalStatus"`,
        { id, userId: user.id, rejectReason },
      );
      await writeHistory(db, user.id, id, '반려', '인증기기를 반려했습니다. 사유: ' + rejectReason);
      await writeNotification(db, device.employeeId, id, 'AUTH_DEVICE_REJECTED', '인증기기 반려', '인증기기 등록 요청이 반려되었습니다. 사유: ' + rejectReason);
      return rows[0];
    });
  }

  @Post('/auth-devices/:authDeviceId/deactivate')
  @HttpCode(200)
  async deactivateAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const id = idOf(req);
    return transaction(async (db) => {
      const device = await loadDevice(db, id);
      if (device.approvalStatus !== '승인') {
        throw new ApiError(409, 'AUTH_DEVICE_NOT_APPROVED', '승인되지 않은 기기입니다.');
      }
      // 가정: 사용중지 처리자·처리 일시도 함께 기록한다
      const rows = await db.query(
        `UPDATE auth_device
            SET use_status = '미사용',
                approver_id = CAST(:userId AS bigint),
                processed_at = now(),
                updated_at = now()
          WHERE auth_device_id = CAST(:id AS bigint)
          RETURNING auth_device_id AS "authDeviceId", use_status AS "useStatus"`,
        { id, userId: user.id },
      );
      await writeHistory(db, user.id, id, '사용중지', '승인된 인증기기를 사용중지했습니다.');
      return rows[0];
    });
  }

  @Delete('/auth-devices/:authDeviceId')
  async deleteAuthDevice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const id = idOf(req);
    return transaction(async (db) => {
      await loadDevice(db, id);
      await writeHistory(db, user.id, id, '삭제', '인증기기를 삭제했습니다.');
      await db.execute(
        `DELETE FROM auth_device WHERE auth_device_id = CAST(:id AS bigint)`,
        { id },
      );
      return {};
    });
  }
}

