import { useState } from 'react';
import { Badge, Band, DataTable, Drawer, ErrorText, Field, Filters, Form, LookupSelect, Pager, Pairs, RefName, Select, TextInput, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['승인', '승인'],
  ['반려', '반려'],
];

type Mode = 'create' | 'approve' | 'reject' | 'deactivate' | 'delete';

export default function FnSfr03703Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState({ status: '', employeeId: '' as number | string });
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [mode, setMode] = useState<Mode | null>(null);
  const [identifier, setIdentifier] = useState('');
  const [deviceName, setDeviceName] = useState('');
  const [rejectReason, setRejectReason] = useState('');

  const isAdmin = role === '시스템 관리자';
  const isEmployee = role === '임직원';

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/auth-devices', role, undefined, {
      approvalStatus: applied.status,
      employeeId: applied.employeeId,
      page,
      size: SIZE,
    }),
    [applied, page, role],
  );

  function search() {
    setPage(0);
    setApplied({ status, employeeId });
  }

  function reset() {
    setStatus('');
    setEmployeeId('');
    setPage(0);
    setApplied({ status: '', employeeId: '' });
  }

  function openMode(next: Mode) {
    setRejectReason('');
    setMode(next);
  }

  function openCreate() {
    setIdentifier('');
    setDeviceName('');
    setMode('create');
  }

  function closeDrawer() {
    setMode(null);
  }

  async function finish(message: string, leaveDetail: boolean) {
    notify(message);
    setMode(null);
    if (leaveDetail) {
      setSelected(null);
    }
    reload();
  }

  async function submitCreate() {
    if (identifier.trim() === '') {
      throw new Error('기기 식별정보를 입력해 주세요.');
    }
    await call('POST', '/auth-devices', role, { deviceIdentifier: identifier.trim(), deviceName: deviceName.trim() });
    await finish('인증기기 등록을 요청했습니다.', false);
  }

  async function submitApprove() {
    await call('POST', '/auth-devices/' + String(selected?.authDeviceId) + '/approve', role, {});
    await finish('인증기기를 승인했습니다.', true);
  }

  async function submitReject() {
    await call('POST', '/auth-devices/' + String(selected?.authDeviceId) + '/reject', role, { rejectReason: rejectReason.trim() });
    await finish('인증기기를 반려했습니다.', true);
  }

  async function submitDeactivate() {
    await call('POST', '/auth-devices/' + String(selected?.authDeviceId) + '/deactivate', role, {});
    await finish('인증기기를 사용중지했습니다.', true);
  }

  async function submitDelete() {
    await call('DELETE', '/auth-devices/' + String(selected?.authDeviceId), role);
    await finish('인증기기를 삭제했습니다.', true);
  }

  function drawer() {
    if (mode === null) {
      return null;
    }
    if (mode === 'create') {
      return (
        <Drawer title="인증기기 등록 요청" onClose={closeDrawer}>
          <Form onSubmit={submitCreate} submit="등록 요청" note="시스템 관리자가 승인하면 2차 인증 로그인에 사용할 수 있습니다.">
            <Field label="기기 식별정보" required wide>
              <TextInput value={identifier} onChange={setIdentifier} placeholder="기기 식별정보를 입력하세요" />
            </Field>
            <Field label="기기명" wide>
              <TextInput value={deviceName} onChange={setDeviceName} placeholder="예: 업무용 휴대전화" />
            </Field>
          </Form>
        </Drawer>
      );
    }
    if (mode === 'approve') {
      return (
        <Drawer title="인증기기 승인" onClose={closeDrawer}>
          <Form onSubmit={submitApprove} submit="승인" note="승인하면 요청자에게 결과가 알려지고 기기를 로그인에 사용할 수 있습니다. 허용 인증기기 수를 넘으면 승인되지 않습니다.">
            <Pairs items={[['기기명', String(selected?.deviceName ?? '')], ['기기 식별정보', String(selected?.deviceIdentifier ?? '')]]} />
          </Form>
        </Drawer>
      );
    }
    if (mode === 'reject') {
      return (
        <Drawer title="인증기기 반려" onClose={closeDrawer}>
          <Form onSubmit={submitReject} submit="반려" danger note="반려하면 요청자에게 결과가 알려지고 다시 승인할 수 없습니다.">
            <Field label="반려 사유" wide>
              <TextInput value={rejectReason} onChange={setRejectReason} multiline placeholder="반려 사유를 입력하세요" />
            </Field>
          </Form>
        </Drawer>
      );
    }
    if (mode === 'deactivate') {
      return (
        <Drawer title="인증기기 사용중지" onClose={closeDrawer}>
          <Form onSubmit={submitDeactivate} submit="사용중지" danger note="사용중지하면 이 기기로는 로그인할 수 없습니다.">
            <Pairs items={[['기기명', String(selected?.deviceName ?? '')]]} />
          </Form>
        </Drawer>
      );
    }
    return (
      <Drawer title="인증기기 삭제" onClose={closeDrawer}>
        <Form onSubmit={submitDelete} submit="삭제" danger note="삭제한 인증기기는 되돌릴 수 없습니다.">
          <Pairs items={[['기기명', String(selected?.deviceName ?? '')]]} />
        </Form>
      </Drawer>
    );
  }

  if (selected !== null) {
    const canProcess = selected.approvalStatus === '신청';
    const canDeactivate = selected.approvalStatus === '승인' && selected.useStatus === '사용';
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>목록으로 돌아가기</button>
        <section className="box">
          <h2>인증기기 정보</h2>
          <Pairs
            items={[
              ['인증기기 ID', String(selected.authDeviceId)],
              ['임직원', <RefName key="emp" table="employee" role={role} value={selected.employeeId} />],
              ['기기명', String(selected.deviceName ?? '')],
              ['기기 식별정보', String(selected.deviceIdentifier ?? '')],
              ['승인 상태', <Badge key="st" value={selected.approvalStatus} />],
              ['사용 여부', <Badge key="us" value={selected.useStatus} />],
            ]}
          />
        </section>
        {isAdmin && (
          <section className="box">
            <h2>처리</h2>
            {canProcess && <button onClick={() => openMode('approve')}>승인</button>}
            {canProcess && <button className="ghost" onClick={() => openMode('reject')}>반려</button>}
            {canDeactivate && <button className="ghost" onClick={() => openMode('deactivate')}>사용중지</button>}
            <button className="ghost" onClick={() => openMode('delete')}>삭제</button>
          </section>
        )}
        {drawer()}
      </div>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>인증기기 승인·관리</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="승인 상태">
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
          <Field label="임직원 ID">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data?.total}>
          {isEmployee && <button onClick={openCreate}>인증기기 등록 요청</button>}
        </Band>
        {error !== '' && <ErrorText text={error} />}
        <DataTable
          columns={[
            { key: 'deviceName', label: '기기명' },
            { key: 'employeeId', label: '임직원 ID', render: (row) => <RefName table="employee" role={role} value={row.employeeId} /> },
            { key: 'deviceIdentifier', label: '기기 식별정보' },
            { key: 'approvalStatus', label: '승인 상태', render: (row) => <Badge value={row.approvalStatus} /> },
            { key: 'useStatus', label: '사용 여부', render: (row) => <Badge value={row.useStatus} /> },
          ]}
          rows={data?.items ?? []}
          onRowClick={(row) => setSelected(row)}
          empty="아직 등록한 인증기기가 없습니다. 인증기기 등록 요청 버튼으로 기기를 등록해 주세요."
        />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {drawer()}
    </div>
  );
}
